+package com.example.customers;
+
+import com.example.customers.domain.*;
+import org.junit.jupiter.api.Test;
+
+import java.util.List;
+import java.util.Set;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+class CustomerRepositoryTest {
+    @Test
+    void filteredPagesAreSortedBeforePagingAndEveryQueryIsRecorded() {
+        QueryLog log = new QueryLog();
+        CustomerRepository repository = new CustomerRepository(log);
+        CustomerFilter filter = new CustomerFilter("MAKINEN", Set.of(CustomerStatus.ACTIVE));
+        List<CustomerSort> sorts = List.of(new CustomerSort("firstName", false));
+        int count = repository.count(filter);
+        var first = repository.findAll(0, 2, sorts, filter);
+        var second = repository.findAll(2, 2, sorts, filter);
+        assertEquals(5, count);
+        assertEquals(List.of("Tomás", "Jarno"), first.stream().map(Customer::firstName).toList());
+        assertEquals(List.of("Ivar", "Elena"), second.stream().map(Customer::firstName).toList());
+        assertEquals(List.of(5), log.countQueries());
+        assertEquals(List.of(new QueryLog.PageQuery(0, 2, 2), new QueryLog.PageQuery(2, 2, 2)),
+                log.pageQueries());
+        assertThrows(IllegalArgumentException.class,
+                () -> repository.findAll(0, 201, sorts, filter));
+    }
+}
